create table if not exists public.dd_underwriting_evidence_register (id uuid primary key default gen_random_uuid(), canonical_sku text not null, division text not null, evidence_type text not null, evidence_source text, evidence_status text not null default 'PENDING', observed_amount numeric, observed_unit text, observed_date date, basis_note text, attribution_status text not null default 'UNALLOCATED', preservation_rule text not null default 'PRESERVE_EXISTING', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.dd_underwriting_evidence_register enable row level security; revoke all on public.dd_underwriting_evidence_register from anon, authenticated; insert into public.dd_underwriting_evidence_register(canonical_sku,division,evidence_type,evidence_source,evidence_status,basis_note) select canonical_sku,division,'SERVICE_MASTER','dd_master_service_universe','PRESENT','Canonical service identity, pricing and existing execution/compliance fields preserved; no overwrite.' from public.dd_master_service_universe where lifecycle_status='CANONICAL_ACTIVE' on conflict do nothing;